float AA = 0.8f;
vec3 waveColor = vec3(0.4f, 0.2f, 0.8f);

float borderCircle(vec2 uv, vec2 p, float r, float border){
    float l = length(uv - p);
    float a = smoothstep(r, r - AA, l);
    r -= border;
    float a1 = smoothstep(r, r - AA, l);
    return a - a1;
}

float circle(vec2 uv, vec2 p, float r){
    float l = length(uv - p);
    float a = smoothstep(r, r - AA, l);
    return a;
}

float sdSegment( in vec2 p, in vec2 a, in vec2 b )
{
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    float v = length( pa - ba*h );
    v = 1.f - step(AA, v);
    return v;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord;
    uv.y = iResolution.y - uv.y;

    vec3 col = vec3(0.f);

    float theta = iTime * 1.5f;

    vec2 pos = vec2(100.f);
    float r = 50.0f; 
    vec2 p1 = vec2(pos.x + (cos(theta) * r), pos.y + (sin(theta) * r));
    col += borderCircle(uv, pos, r, 1.f);
    col += sdSegment(uv, pos, p1);

    vec2 p2 = vec2(pos.x + r, p1.y);
    col += sdSegment(uv, p1, p2);
    if(uv.x > p2.x){
        float x = uv.x - p2.x;
        float y = sin(theta - (x / r)) * r;
        col += circle(uv, vec2(uv.x, pos.y + y), 1.f) * waveColor;
    }

    vec2 p3 = vec2(p1.x, pos.y + r);
    col += sdSegment(uv, p1, p3);
    if(uv.y > p3.y){
        float y = uv.y - p3.y;
        float x = cos(theta - (y / r)) * r;
        col += circle(uv, vec2(x + pos.x, uv.y), 1.f) * waveColor;
    }

    fragColor = vec4(col,1.0);
}
